<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/functions.php';
if (!isset($_SESSION['user_id']) || ($_SESSION['role'] ?? '') !== 'portal_admin') { http_response_code(403); exit('Access denied.'); }
$id=(int)$_SESSION['user_id'];
$stmt=$pdo->prepare('SELECT first_name,middle_name,last_name,email,phone FROM users WHERE id=?'); $stmt->execute([$id]); $admin=$stmt->fetch(PDO::FETCH_ASSOC);
if (!$admin) { http_response_code(404); exit('Account not found.'); }
$msg=''; $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 $token=$_POST['csrf_token']??'';
 if (!hash_equals((string)csrf_token(),(string)$token)) $error='Your session token is invalid. Please refresh and try again.';
 else {
  $first=trim($_POST['first_name']??''); $middle=trim($_POST['middle_name']??''); $last=trim($_POST['last_name']??''); $email=trim($_POST['email']??''); $phone=trim($_POST['phone']??'');
  if ($first==='' || $last==='' || !filter_var($email,FILTER_VALIDATE_EMAIL)) $error='Please enter a valid first name, last name and email address.';
  else {
   $check=$pdo->prepare('SELECT id FROM users WHERE email=? AND id<>? LIMIT 1'); $check->execute([$email,$id]);
   if ($check->fetch()) $error='That email address is already used by another account.';
   else { $upd=$pdo->prepare('UPDATE users SET first_name=?,middle_name=?,last_name=?,email=?,phone=? WHERE id=?'); $upd->execute([$first,$middle,$last,$email,$phone,$id]);
    $admin=['first_name'=>$first,'middle_name'=>$middle,'last_name'=>$last,'email'=>$email,'phone'=>$phone]; $_SESSION['first_name']=$first; $_SESSION['last_name']=$last; $_SESSION['email']=$email; $msg='Your profile has been updated.';
   }
  }
 }
}
function settings_e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
